function countInt(values: seq<object>) : int
    requires values != null
    ensures countInt(values) >= 0
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= i <= |values|
        invariant count == CountInt(values, 0, i)
    {
        if values[i] is int then
            count := count + 1;
        i := i + 1;
    }
    return count;
}

function CountInt(values: seq<object>, count: int, index: int) : int
